/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { HeatTransferScreen } from "../../src/combined/HeatTransferScreen.js";
import { ConductionScreen } from "../../src/conduction/ConductionScreen.js";
import { ConvectionScreen } from "../../src/convection/ConvectionScreen.js";
import HeatTransferColors from "../../src/HeatTransferColors.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { MaterialsScreen } from "../../src/materials/MaterialsScreen.js";
import { HeatTransferPreferencesModel } from "../../src/preferences/HeatTransferPreferencesModel.js";
import { TemperatureScreen } from "../../src/temperature/TemperatureScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();
  const preferences = new HeatTransferPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screenNames = stringManager.getScreenNames();

  const screens = [
    new TemperatureScreen({
      name: screenNames.temperatureStringProperty,
      tandem: Tandem.ROOT.createTandem("temperatureScreen"),
      backgroundColorProperty: HeatTransferColors.backgroundColorProperty,
      preferences,
    }),
    new ConductionScreen({
      name: screenNames.conductionStringProperty,
      tandem: Tandem.ROOT.createTandem("conductionScreen"),
      backgroundColorProperty: HeatTransferColors.backgroundColorProperty,
      preferences,
    }),
    new ConvectionScreen({
      name: screenNames.convectionStringProperty,
      tandem: Tandem.ROOT.createTandem("convectionScreen"),
      backgroundColorProperty: HeatTransferColors.backgroundColorProperty,
      preferences,
    }),
    new HeatTransferScreen({
      name: screenNames.combinedStringProperty,
      tandem: Tandem.ROOT.createTandem("combinedScreen"),
      backgroundColorProperty: HeatTransferColors.backgroundColorProperty,
      preferences,
    }),
    new MaterialsScreen({
      name: screenNames.materialsStringProperty,
      tandem: Tandem.ROOT.createTandem("materialsScreen"),
      backgroundColorProperty: HeatTransferColors.backgroundColorProperty,
      preferences,
    }),
  ];

  return { screens, tracked: { HeatTransferColors, stringManager, preferences } };
}

let built: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    built = buildSim();
    return built.screens;
  },
  tracked: () => built?.tracked ?? {},
});
